async function connect(){
 const transport=new StdioClientTransport({command:config.command,args:config.args,env:{...process.env,...config.env},stderr:'inherit'});
 const client=new Client({name:'gbrain-install-verifier',version:'1.0.0'},{capabilities:{}});
 await client.connect(transport);return client;
}
function payload(r){if(r.isError)throw Error(JSON.stringify(r));for(const c of r.content??[]){if(c.type==='text'){try{return JSON.parse(c.text)}catch{}}}throw Error('No JSON payload: '+JSON.stringify(r));}
async function call(c,name,args){return payload(await c.callTool({name,arguments:{...args,_meta:{hot_memory:'off'}}}));}
const marker='gbrain-mcp-install-check-'+crypto.randomBytes(6).toString('hex');
let c=await connect();
const tools=await c.listTools();
console.log('MCP initialized; tools:',tools.tools.map(t=>t.name).join(', '));
