console.log('PASS MCP persistence after server/client reopen:',id);
const forgotten=await call(c,'forget',{id,reason:'install-check cleanup'});
console.log('MCP forget:',JSON.stringify(forgotten));
recalled=await call(c,'recall',{query:marker});
if((recalled.facts??[]).some(f=>String(f.id??f.fact_id)===id))throw Error('Fact remains active');
console.log('PASS MCP cleanup: fixture absent from active recall');
await c.close();
fs.writeFileSync('/tmp/gbrain-install-docs/mcp-roundtrip-result.json',JSON.stringify({passed:true,id,checks:['initialize','tools/list','remember','recall','reopen','recall','forget','recall-absent']},null,2));

